// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 so Collect is not blocked
        c.SetMinSum(0);
        c.Initialized();

        // Alice deposits 10, Bob deposits 20
        address alice = address(0x1111);
        address bob = address(0x2222);
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();
        vm.deal(bob, 20);
        vm.prank(bob);
        c.Deposit{value: 20}();

        // Alice Collect(8)
        vm.prank(alice);
        c.Collect(8);

        // In reference P: balances[alice] = 10 - 8 = 2, balances[bob] = 20
        // In bug M: balances[alice] = 8 - 10 = -2 underflows (reverts) OR if uint256 wraps to 2^256-2 then balances[alice] huge
        // Actually bug M does: balances[msg.sender] = _am - balances[msg.sender] = 8 - 10 = underflow revert (since 8<10)
        // So Collect reverts. Need to handle revert case: use try/catch

        // Check if Collect succeeded or reverted for Alice
        bool success;
        try c.Collect(8) { success = true; } catch { success = false; }
        // Since Alice already called Collect once, second call: balances[alice]=2 < MinSum(=0) and >= _am? 2>=0 && 2>=8 false => do nothing, but in reference still balances[alice]=2
        // Better: after first Collect, check balances[alice]
        // Actually simpler: after first Collect (the one we already did), check balances[alice]
        // But we need to observe divergence after the Collect call. Since the bug would have reverted the first Collect, we can check if the state changed
        // Re-run the sequence with a fresh contract
        // Reset
        delete c;
        c = new C();
        c.SetMinSum(0);
        c.Initialized();

        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();
        vm.deal(bob, 20);
        vm.prank(bob);
        c.Deposit{value: 20}();

        // In reference P, Collect(8) succeeds; in bug M it reverts due to underflow
        bool ok;
        vm.prank(alice);
        try c.Collect(8) { ok = true; } catch { ok = false; }

        // In reference, ok = true; in bug, ok = false
        assertTrue(ok, "Collect should succeed in reference, but bug causes revert");
    }
}

