        c.SetMinSum(0);
        vm.prank(address(this));
        c.SetLogFile(address(0xdead));
        vm.prank(address(this));
        c.Initialized();

        // Alice deposits 10 wei
        address alice = address(0x1234);
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Deposit{value: 10}();

        // Now attempt Collect(15) — in reference, 10 - 15 underflows (reverts)
        // In buggy, 15 - 10 = 5 (succeeds)
        bool ok;
        vm.prank(alice);
        try c.Collect(15) { ok = true; } catch { ok = false; }

        // Reference should revert (ok = false), buggy should succeed (ok = true)
        // Assert that the reference (correct) behavior is to revert
        assertTrue(!ok, "Collect should have reverted in the correct contract");
    }
}

