pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a receiver that rejects all calls to simulate a revert on Collect
        address receiver = address(new Receiver());
        vm.deal(receiver, 0);

        // Setup: Set MinSum to 1 wei, LogFile to any address (but we won't use it), initialize
        c.SetMinSum(1);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the receiver with 10 ether via deposit
        vm.deal(receiver, 10 ether);
        vm.prank(receiver);
        c.Deposit{value: 10 ether}();

        // Now receiver calls Collect(5 ether) – this will attempt to send 5 ether back to receiver
        // Receiver's fallback reverts, so on reference the call reverts
        vm.prank(receiver);
        bool ok;
        try c.Collect(5 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // On reference, ok is false because of revert in fallback
        // On buggy version, the balances are updated BEFORE the call, so even if call reverts,
        // balances[receiver] becomes 15 ether (10 + 5) and the function returns successfully (ok = true)
        // Assert the condition that holds on reference (revert) but fails on buggy (no revert)
        assertTrue(!ok, "Reference should revert due to failed external call");
    }
}

contract Receiver {
    fallback() external payable {
        revert("reject");
    }
    receive() external payable {
        revert("reject");
    }
}

