import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 so that any balance >= 0 passes the first check
        c.SetMinSum(0);

        // Initialize the contract to prevent reinitialization
        c.Initialized();

        // Give user 1 ether for gas and deposit 10 wei
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Deposit{value: 10}();

        // Now call Collect(1) — in the reference, the call to LogFile (which is at address(0)) will revert
        // because the external call to Log.AddMessage fails, causing the whole transaction to revert.
        // In the mutant, the log call is removed, so Collect(1) succeeds.
        bool ok;
        vm.prank(user);
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: Collect reverts => ok == false
        // Mutant: Collect succeeds => ok == true
        assertTrue(ok == false, "Expected revert in reference, mutant should succeed");
    }
}

